     toml::from_str(content).unwrap_or_else(|e| {
-        let _ = log::warn(format!("Failed to parse spark.toml, using defaults: {e}"));
+        log::warn(format!("Failed to parse spark.toml, using defaults: {e}"));
         SparkConfig::default()
     })
 }

